css:
/* 素笺：纸质极简。日/夜双版；正文首字下沉用 ::first-letter，装饰不占正文测量 */
:root{
  --mi-bg:#f7f4ec; --mi-fg:#2a2620; --mi-dim:#8a8175; --mi-line:#d9d2c4;
}
[data-reader-theme="night"]{
  --mi-bg:#15161a; --mi-fg:#d6d3cc; --mi-dim:#8b8880; --mi-line:#33353c;
}
html,body{margin:0;padding:0;background:var(--mi-bg);color:var(--mi-fg);
  font-family:-apple-system,"Noto Serif CJK SC","Source Han Serif SC",Georgia,serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.9);}
.mi-sheet{position:relative;padding:1.1em 1.4em 0;}
.mi-spine{position:absolute;left:.55em;top:1.1em;bottom:.6em;width:1px;background:var(--mi-line);}
.mi-head{padding-left:.35em;font-size:.78em;letter-spacing:.3em;color:var(--mi-dim);
  border-bottom:1px solid var(--mi-line);padding-bottom:.5em;}
.mi-hero{padding:.9em .35em .2em;}
.mi-hero-title{display:block;font-size:1.62em;font-weight:600;letter-spacing:.14em;line-height:1.35;}
.mi-hero-sub{display:block;margin-top:.4em;font-size:.76em;letter-spacing:.52em;color:var(--mi-dim);}
.mi-hero-rule{display:block;width:2.4em;height:1px;margin-top:.85em;background:var(--mi-dim);opacity:.6;}
.mi-body{padding-left:.35em;padding-top:.7em;}
.mi-body .reader-chapter-title{margin:0 0 .9em;font-size:1.3em;font-weight:600;letter-spacing:.06em;}
.mi-body p{margin:0 0 1em;}
.mi-body .reader-paragraph{text-indent:2em;}
.mi-body .reader-paragraph:first-of-type::first-letter{float:left;font-size:2.6em;line-height:.92;
padding:.06em .12em 0 0;color:var(--mi-fg);}
.mi-body a{color:inherit;text-decoration:underline;text-decoration-color:var(--mi-line);
  text-underline-offset:.18em;}
.mi-body blockquote{margin:0 0 1em;padding:.3em 0 .3em .9em;border-left:2px solid var(--mi-line);color:var(--mi-dim);}
.mi-body code{font-family:"JetBrains Mono",Consolas,monospace;font-size:.9em;
  background:rgba(127,127,127,.12);padding:.12em .32em;border-radius:3px;}
.mi-body pre{background:rgba(127,127,127,.1);padding:.8em;border-radius:4px;overflow-x:auto;}
.mi-body table{width:100%;border-collapse:collapse;}
.mi-body th,.mi-body td{border:1px solid var(--mi-line);padding:.35em .55em;}
.mi-foot{display:flex;justify-content:space-between;align-items:center;
  margin:0 .35em;padding:.55em 0 .7em;font-size:.72em;color:var(--mi-dim);
  border-top:1px solid var(--mi-line);font-variant-numeric:tabular-nums;}
.mi-dot{flex:1;margin:0 .8em;height:1px;background:var(--mi-line);}

javascript:
(function () {
  'use strict';
  // 每页动效。只使用双方共有的 readerTemplate 钩子 API + Web Animations
  // => 同一份主题在我们与 archive 两个引擎上行为一致（互兼容目标）。
  var anims = [], active = null;
  function stop() {
    for (var i = 0; i < anims.length; i++) { anims[i].cancel(); }
    anims = []; active = null;
  }
  function play(node, frames, dur, delay, easing) {
    if (!node || typeof node.animate !== 'function') return;
    anims.push(node.animate(frames, {
      duration: dur, delay: delay || 0, iterations: Infinity, easing: easing || 'ease-in-out'
    }));
  }
  function all(root, sel) {
    return root ? Array.prototype.slice.call(root.querySelectorAll(sel)) : [];
  }
  function start(page) {
    active = page;
    // 小视口不做装饰动效（与 archive 主题同判据，避免小窗下动效抢帧）
    if (readerTemplate.viewport.height <= 440) return;
    var i;

    // 素笺：书脊呼吸 + 圆点脉动 + 分隔线伸缩
    play(page.querySelector('.mi-spine'), [{ opacity: 0.35 }, { opacity: 0.85 }, { opacity: 0.35 }], 4200);
    var dots = all(page, '.mi-dot');
    for (i = 0; i < dots.length; i++) {
      play(dots[i], [{ transform: 'scale(0.8)', opacity: 0.5 }, { transform: 'scale(1.1)', opacity: 1 }, { transform: 'scale(0.8)', opacity: 0.5 }], 2800, -i * 420);
    }
    play(page.querySelector('.mi-hero-rule'), [{ transform: 'scaleX(0.5)', opacity: 0.4 }, { transform: 'scaleX(1)', opacity: 0.9 }, { transform: 'scaleX(0.5)', opacity: 0.4 }], 3600);
  }
  // 结算后旧节点可能已脱离文档 => 先停旧动画（换壳/重排后由 motionChange 重新起）
  readerTemplate.on('afterLayout', function () { stop(); });
  readerTemplate.on('motionChange', function (event) {
    if (!event.page || event.state === 'settled' || event.reducedMotion) { stop(); return; }
    if (event.state === 'paused') {
      for (var i = 0; i < anims.length; i++) { anims[i].pause(); }
      return;
    }
    if (active === event.page) {
      for (var j = 0; j < anims.length; j++) { anims[j].play(); }
      return;
    }
    stop(); start(event.page);
  });
  readerTemplate.on('dispose', stop);
})();
